+
+  /// A provider request went out: begin watching its silent window. Arms
+  /// over a stale watch (a new request restarts the elapsed base — the
+  /// old request is over).
+  void requestStarted() {
+    _since = _clock();
+    if (_timer == null) _arm();
+  }
+
