/// The already-cancelled turn: no request leaves the loop.
Future<(AssistantMessage, Context)> _abortedTurn(
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
) async {
  return (
    await _finishWithoutStream(
      context,
