    try {
      final queue = resolveProviderQueueAtBoot(
        projectDir: config.env.cwd,
        homeDir: config.homeDir ?? config.env.cwd,
        env: config.providerQueueEnv,
      );
      config.providersQueueRuntime = queue.entries.isEmpty
          ? null
