      final cli = cliFor(
        fake.call,
        streamThinking: true,
        useColor: true,
        markdownSurface: const MarkdownSurface(mode: MarkdownSurfaceMode.ansi),
      );
      final run = cli.run();
      io.sendLine('hi');
      await waitForIt(() => fake.calls == 1 && !cli.isBusy);
      io.sendLine('/exit');
      await run;

