    io: io,
    streamFunction: fake,
    useColor: useColor,
    useTui: useTui,
    markdownSurface: markdownSurface,
    waitingClock: () => now,
  );

  group('AC1: line mode, flag on', () {
    test('thinking deltas print dimmed, in order, before the answer; '
