Future<(AssistantMessage, Context)> _abortedTurn(
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
) async {
  return (
    await _finishWithoutStream(
      context,
      emit,
      _terminalMessage(config.model, StopReason.aborted, 'Operation aborted'),
