    if (globalValue != null) {
      final stdio = _stdioServerRefusal(segments, globalValue);
      if (stdio != null) {
        return ConfigGetResult(
          key: key,
          found: false,
          notApplicable: _mcpStdioNote(stdio),
        );
      }
      return ConfigGetResult(
        key: key,
        found: true,
        display: _display(globalValue),
        scope: 'global',
        file: globalConfigPath,
