  Future<void> _providerQueueAdd(
    String kind,
    String model,
    String? apiKeyEnv,
    String? baseUrl,
  ) async {
    final ProviderQueueEntry entry;
    try {
      entry = ProviderQueueEntry(
        providerType: kind,
        model: model,
        apiKeyEnv: apiKeyEnv,
        baseUrl: baseUrl,
      );
    } on ArgumentError catch (error) {
      io.writeln('/providers queue add refused: ${error.message}');
