  tearDown(() => io.close());

  AgentCli cliFor(
    StreamFunction fake, {
    bool streamThinking = false,
    bool useColor = false,
    MarkdownSurface? markdownSurface,
    bool useTui = false,
    WaitingConfig waiting = const WaitingConfig(),
