      final toolPartial = testAssistant(
        content: [
          ThinkingContent(thinking: 'why not'),
          TextContent(text: 'let me check'),
          call,
        ],
        stopReason: StopReason.toolUse,
      );
      final firstTurn = <AssistantMessageEvent>[
        StartEvent(partial: empty),
