          delta: 'think B',
          partial: testAssistant(
            content: [
              TextContent(text: 'part one. '),
              ThinkingContent(thinking: 'think B'),
            ],
          ),
        ),
        TextDeltaEvent(
          contentIndex: 3,
          delta: 'part two',
          partial: testAssistant(
            content: [TextContent(text: 'part one. part two')],
          ),
        ),
        DoneEvent(
          reason: StopReason.stop,
          message: testAssistant(
