    if (errors.isNotEmpty) {
      throw ConfigException(errors.map((e) => e.message).join('; '));
    }
    switch (await env.writeFile(file, normalized)) {
      case Err(:final error):
        throw ConfigException('cannot write $file: $error');
      case Ok():
