  Context context,
  AgentEventSink emit,
  AssistantMessage message, {
  bool replaceLast = false,
}) async {
  if (replaceLast) {
    context.messages[context.messages.length - 1] = message;
  } else {
    context.messages.add(message);
    await emit(MessageStartEvent(message));
  }
  await emit(MessageEndEvent(message));
  return message;
}

