        if (stdio != null) {
          return ConfigGetResult(
            key: key,
            found: false,
            notApplicable: _mcpStdioNote(stdio),
          );
        }
        return ConfigGetResult(
          key: key,
          found: true,
          display: _display(projectValue),
          scope: 'project',
